import pandas as pd
import numpy as np

# Load data
trip_data = pd.read_csv('chunks_csv/cyclehire_w007.csv')
adj_data = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Step 1: Compute self-containment ratios
departures = trip_data.groupby('StartBorough').size().rename('departures')
self_contained = trip_data[trip_data['StartBorough'] == trip_data['EndBorough']].groupby('StartBorough').size().rename('self_contained')
ratio_df = pd.concat([departures, self_contained], axis=1)
ratio_df['ratio'] = ratio_df['self_contained'] / ratio_df['departures']

# Step 2: Build adjacency graph
graph = {}
for _, row in adj_data.iterrows():
    a, b = row['borough'], row['neighbor']
    if a not in graph:
        graph[a] = set()
    graph[a].add(b)
    if b not in graph:
        graph[b] = set()
    graph[b].add(a)

# Find common boroughs with at least one neighbor in the graph
boroughs_ratio = set(ratio_df.index)
boroughs_graph = set(graph.keys())
common_boroughs = boroughs_ratio & boroughs_graph
common_boroughs = [b for b in common_boroughs if len(graph[b] & common_boroughs) > 0]
common_boroughs_list = sorted(common_boroughs)
n_boroughs = len(common_boroughs)

# Filter ratio data to common boroughs
ratio_common = ratio_df.loc[common_boroughs_list]

# Step 3: Center ratios and compute global variance
ratios = ratio_common['ratio'].values
mean_ratio = np.mean(ratios)
z = ratios - mean_ratio
if n_boroughs > 1:
    s2 = np.sum(z**2) / (n_boroughs - 1)
else:
    s2 = 0.0

# Create Series for centered ratios
z_series = pd.Series(z, index=common_boroughs_list)

# Step 4: Compute observed spatial lag and Local Moran's I
lag_obs = {}
I_obs = {}
for borough in common_boroughs_list:
    neighbors = list(graph[borough] & set(common_boroughs_list))
    if neighbors:
        lag_i = z_series[neighbors].mean()
    else:
        lag_i = 0.0
    lag_obs[borough] = lag_i
    I_obs[borough] = (z_series[borough] * lag_i) / s2 if s2 != 0 else 0

# Step 5: Permutation test
n_perm = 500
index_map = {borough: idx for idx, borough in enumerate(common_boroughs_list)}
neighbor_indices = {}
for borough in common_boroughs_list:
    nbrs = graph[borough] & set(common_boroughs_list)
    neighbor_indices[borough] = [index_map[n] for n in nbrs]

z_obs_vector = z_series.values
count_positive = {borough: 1 for borough in common_boroughs_list}
count_negative = {borough: 1 for borough in common_boroughs_list}

for _ in range(n_perm):
    perm_z = np.random.permutation(z_obs_vector)
    if n_boroughs > 1:
        s2_perm = np.sum(perm_z**2) / (n_boroughs - 1)
    else:
        s2_perm = 0.0

    for borough in common_boroughs_list:
        idx_i = index_map[borough]
        z_i_perm = perm_z[idx_i]
        nbr_idx = neighbor_indices[borough]
        if nbr_idx:
            lag_i_perm = np.mean(perm_z[nbr_idx])
        else:
            lag_i_perm = 0.0
        I_i_perm = (z_i_perm * lag_i_perm) / s2_perm if s2_perm != 0 else 0

        obs_I = I_obs[borough]
        if obs_I > 0 and I_i_perm >= obs_I:
            count_positive[borough] += 1
        elif obs_I < 0 and I_i_perm <= obs_I:
            count_negative[borough] += 1

# Compute p-values
p_values = {}
for borough in common_boroughs_list:
    obs_I = I_obs[borough]
    if obs_I > 0:
        p_values[borough] = count_positive[borough] / 501.0
    elif obs_I < 0:
        p_values[borough] = count_negative[borough] / 501.0
    else:
        p_values[borough] = 1.0

# Step 6: Identify hotspots (HH) and coldspots (LL)
results = []
for borough in common_boroughs_list:
    p_val = p_values[borough]
    z_val = z_series[borough]
    lag_val = lag_obs[borough]
    if p_val < 0.05:
        if z_val > 0 and lag_val > 0:
            results.append((borough, 'HH', p_val))
        elif z_val < 0 and lag_val < 0:
            results.append((borough, 'LL', p_val))

# Output results
print(f"data_points_used = {n_boroughs}")
if not results:
    print("FINAL ANSWER: none")
else:
    formatted_results = []
    for name, spot_type, p_val in results:
        ratio_val = ratio_common.loc[name, 'ratio']
        formatted_results.append(f"{name} ({spot_type}, statistical method={p_val:.3f})")
    print("FINAL ANSWER: " + ", ".join(formatted_results))
